  4 | const initialState: PlayerState = {
  5 |   currentTrack: null,
  6 |   isPlaying: false,
  7 |   volume: 100,
  8 |   currentTime: 0,
  9 |   duration: 0,
 10 |   playlist: [],
 11 |   repeatMode: "none",
 12 |   isShuffled: false,
