 15 | function shuffleArray<T>(array: T[]): T[] {
 16 |   const shuffled = [...array];
 17 |   for (let i = shuffled.length - 1; i > 0; i--) {
 18 |     const j = Math.floor(Math.random() * (i + 1));
 19 |     [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
 20 |   }
 21 |   return shuffled;
 22 | }
