 24 | function playerReducer(state: PlayerState, action: PlayerAction): PlayerState {
 25 |   switch (action.type) {
 26 |     case "PLAY": {
 27 |       const track = action.track ?? state.currentTrack;
 28 |       if (!track && state.playlist.length === 0) return state;
 29 |       const targetTrack = track ?? state.playlist[0];
 30 |       return {
 31 |         ...state,
 32 |         currentTrack: targetTrack,
 33 |         isPlaying: true,
 34 |         currentTime: 0,
 35 |         duration: targetTrack.duration,
 36 |       };
 37 |     }
 38 | 
 39 |     case "PAUSE":
 40 |       return { ...state, isPlaying: false };
 41 | 
 42 |     case "STOP":
 43 |       return { ...state, isPlaying: false, currentTime: 0 };
 44 | 
 45 |     case "NEXT": {
 46 |       if (state.playlist.length === 0) return state;
 47 |       const currentIndex = state.playlist.findIndex(
 48 |         (t) => t.id === state.currentTrack?.id
 49 |       );
 50 |       const nextIndex = (currentIndex + 1) % state.playlist.length;
 51 |       const nextTrack = state.playlist[nextIndex];
 52 |       return {
 53 |         ...state,
 54 |         currentTrack: nextTrack,
 55 |         isPlaying: true,
 56 |         currentTime: 0,
 57 |         duration: nextTrack.duration,
 58 |       };
 59 |     }
 60 | 
 61 |     case "PREV": {
 62 |       if (state.playlist.length === 0) return state;
 63 |       const currentIndex = state.playlist.findIndex(
 64 |         (t) => t.id === state.currentTrack?.id
 65 |       );
 66 |       const prevIndex =
 67 |         currentIndex <= 0
 68 |           ? state.playlist.length - 1
 69 |           : currentIndex - 1;
 70 |       const prevTrack = state.playlist[prevIndex];
 71 |       return {
 72 |         ...state,
 73 |         currentTrack: prevTrack,
 74 |         isPlaying: true,
 75 |         currentTime: 0,
 76 |         duration: prevTrack.duration,
 77 |       };
 78 |     }
 79 | 
 80 |     case "SEEK":
 81 |       return { ...state, currentTime: Math.max(0, Math.min(action.time, state.duration)) };
 82 | 
 83 |     case "SET_VOLUME":
 84 |       return { ...state, volume: Math.max(0, Math.min(100, action.volume)) };
 85 | 
 86 |     case "LOAD_PLAYLIST":
 87 |       return {
 88 |         ...state,
 89 |         playlist: action.tracks,
 90 |         currentTrack: action.tracks[0] ?? null,
 91 |         currentTime: 0,
 92 |         duration: action.tracks[0]?.duration ?? 0,
 93 |         isPlaying: false,
 94 |       };
 95 | 
 96 |     case "ADD_TRACK":
 97 |       return { ...state, playlist: [...state.playlist, action.track] };
 98 | 
 99 |     case "REMOVE_TRACK":
100 |       return {
101 |         ...state,
102 |         playlist: state.playlist.filter((t) => t.id !== action.trackId),
103 |         currentTrack:
104 |           state.currentTrack?.id === action.trackId
105 |             ? null
106 |             : state.currentTrack,
107 |       };
108 | 
109 |     case "REORDER_PLAYLIST":
110 |       return { ...state, playlist: action.tracks };
111 | 
112 |     case "SET_REPEAT_MODE":
113 |       return { ...state, repeatMode: action.mode };
114 | 
115 |     case "TOGGLE_SHUFFLE": {
116 |       if (state.isShuffled) {
117 |         return { ...state, isShuffled: false };
118 |       }
119 |       return { ...state, isShuffled: true, playlist: shuffleArray(state.playlist) };
120 |     }
121 | 
122 |     case "SET_DURATION":
123 |       return { ...state, duration: action.duration };
124 | 
125 |     case "SET_CURRENT_TIME":
126 |       return { ...state, currentTime: action.time };
127 | 
128 |     default:
129 |       return state;
130 |   }
131 | }
