133 | export function usePlayer(initialPlaylist: Track[] = []) {
134 |   const [state, dispatch] = useReducer(playerReducer, {
135 |     ...initialState,
136 |     playlist: initialPlaylist,
137 |     currentTrack: initialPlaylist[0] ?? null,
138 |     duration: initialPlaylist[0]?.duration ?? 0,
139 |   });
140 | 
141 |   const play = useCallback((track?: Track) => dispatch({ type: "PLAY", track }), []);
142 |   const pause = useCallback(() => dispatch({ type: "PAUSE" }), []);
143 |   const stop = useCallback(() => dispatch({ type: "STOP" }), []);
144 |   const next = useCallback(() => dispatch({ type: "NEXT" }), []);
145 |   const prev = useCallback(() => dispatch({ type: "PREV" }), []);
146 |   const seek = useCallback((time: number) => dispatch({ type: "SEEK", time }), []);
147 |   const setVolume = useCallback((volume: number) => dispatch({ type: "SET_VOLUME", volume }), []);
148 |   const loadPlaylist = useCallback((tracks: Track[]) => dispatch({ type: "LOAD_PLAYLIST", tracks }), []);
149 |   const addTrack = useCallback((track: Track) => dispatch({ type: "ADD_TRACK", track }), []);
150 |   const removeTrack = useCallback((trackId: string) => dispatch({ type: "REMOVE_TRACK", trackId }), []);
151 |   const reorderPlaylist = useCallback((tracks: Track[]) => dispatch({ type: "REORDER_PLAYLIST", tracks }), []);
152 |   const setRepeatMode = useCallback((mode: RepeatMode) => dispatch({ type: "SET_REPEAT_MODE", mode }), []);
153 |   const toggleShuffle = useCallback(() => dispatch({ type: "TOGGLE_SHUFFLE" }), []);
154 |   const setDuration = useCallback((duration: number) => dispatch({ type: "SET_DURATION", duration }), []);
155 |   const setCurrentTime = useCallback((time: number) => dispatch({ type: "SET_CURRENT_TIME", time }), []);
156 | 
157 |   return {
158 |     state,
159 |     play,
160 |     pause,
161 |     stop,
162 |     next,
163 |     prev,
164 |     seek,
165 |     setVolume,
166 |     loadPlaylist,
167 |     addTrack,
168 |     removeTrack,
169 |     reorderPlaylist,
170 |     setRepeatMode,
171 |     toggleShuffle,
172 |     setDuration,
173 |     setCurrentTime,
174 |   };
175 | }
